{"command":"cd /workspace && cat > token.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"unicode"
	"unicode/utf8"
)

// tokenKind identifies what a piece of a statement represents.
type tokenKind int

const (
	tkError tokenKind = iota
	tkIgnore

	// path pieces
	tkBare
	tkNumericKey
	tkQuotedKey
	tkDot
	tkLBrace
	tkRBrace

	// separators
	tkEquals
	tkSemi

	// values
	tkString
	tkNumber
	tkTrue
	tkFalse
	tkNull
	tkEmptyArray
	tkEmptyObject
)

// token is a single lexical element of a gron statement.
type token struct {
	text string
	kind tokenKind
}

// isValue reports whether the token holds a value.
func (t token) isValue() bool {
	switch t.kind {
	case tkString, tkNumber, tkTrue, tkFalse, tkNull, tkEmptyArray, tkEmptyObject:
		return true
	}
	return false
}

// plain renders the token without any colour.
func (t token) plain() string {
	if t.kind == tkEquals {
		return " " + t.text + " "
	}
	return t.text
}

// painted renders the token with terminal colours.
func (t token) painted(p *palette) string {
	switch t.kind {
	case tkBare:
		return p.bare(t.text)
	case tkNumericKey, tkNumber:
		return p.num(t.text)
	case tkQuotedKey, tkString:
		return p.str(t.text)
	case tkLBrace, tkRBrace, tkEmptyArray, tkEmptyObject:
		return p.brace(t.text)
	case tkTrue, tkFalse, tkNull:
		return p.lit(t.text)
	case tkEquals:
		return " " + t.text + " "
	}
	return t.text
}

// identStart reports whether r may begin a bare identifier.
func identStart(r rune) bool {
	if r == '$' || r == '_' {
		return true
	}
	return unicode.In(r, unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl)
}

// identPart reports whether r may appear after the first rune of a bare
// identifier.
func identPart(r rune) bool {
	if identStart(r) {
		return true
	}
	return unicode.In(r, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc)
}

var jsReserved = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true,
	"continue": true, "debugger": true, "default": true, "delete": true,
	"do": true, "else": true, "export": true, "extends": true, "false": true,
	"finally": true, "for": true, "function": true, "if": true, "import": true,
	"in": true, "instanceof": true, "new": true, "null": true, "return": true,
	"super": true, "switch": true, "this": true, "throw": true, "true": true,
	"try": true, "typeof": true, "var": true, "void": true, "while": true,
	"with": true, "yield": true,
}

// isBareKey reports whether s can be written as `.s` instead of `["s"]`.
func isBareKey(s string) bool {
	if s == "" || jsReserved[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !identStart(r) {
				return false
			}
			continue
		}
		if !identPart(r) {
			return false
		}
	}
	return true
}

// gronQuote produces the quoted form of a string as used in gron output.
func gronQuote(s string) string {
	var b bytes.Buffer
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '\\':
			b.WriteString(`\\`)
		case '"':
			b.WriteString(`\"`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '\u2028', '\u2029':
			fmt.Fprintf(&b, `\u%04x`, r)
		default:
			if unicode.IsControl(r) {
				fmt.Fprintf(&b, `\u%04X`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

var _ = utf8.RuneError
EOF"}

