package main

import (
	"os"
	"syscall"
	"unsafe"
)

// palette wraps strings in ANSI escape sequences. When codes is false the
// strings are returned untouched (this mirrors the NO_COLOR behaviour).
type palette struct {
	codes bool
}

func (p *palette) wrap(open, close, s string) string {
	if !p.codes {
		return s
	}
	return "\x1b[" + open + "m" + s + "\x1b[" + close + "m"
}

// bare keys / object field names: bold blue
