package main

import (
	"encoding/json"
	"strconv"
	"strings"
)

// statement is a gron assignment, e.g. json.a[0] = "x";
type statement []token

// plain renders the statement without colour.
func (s statement) plain() string {
	var b strings.Builder
	for _, t := range s {
		b.WriteString(t.plain())
	}
	return b.String()
}

// painted renders the statement with colour.
func (s statement) painted(p *palette) string {
	var b strings.Builder
	for _, t := range s {
		b.WriteString(t.painted(p))
	}
	return b.String()
}

// extend returns a copy of the statement with extra tokens appended.
func (s statement) extend(ts ...token) statement {
	out := make(statement, 0, len(s)+len(ts)+3)
	out = append(out, s...)
	return append(out, ts...)
}

func (s statement) withKey(k string) statement {
	if isBareKey(k) {
		return s.extend(token{".", tkDot}, token{k, tkBare})
	}
	return s.extend(token{"[", tkLBrace}, token{gronQuote(k), tkQuotedKey}, token{"]", tkRBrace})
}

func (s statement) withIndex(i int) statement {
	return s.extend(token{"[", tkLBrace}, token{strconv.Itoa(i), tkNumericKey}, token{"]", tkRBrace})
}

// assign produces the full statement for a path and a value token.
func (s statement) assign(v token) statement {
	return s.extend(token{"=", tkEquals}, v, token{";", tkSemi})
}

// valueToken converts a decoded JSON value into its gron value token.
func valueToken(v interface{}) token {
	switch vv := v.(type) {
	case map[string]interface{}:
		return token{"{}", tkEmptyObject}
	case []interface{}:
		return token{"[]", tkEmptyArray}
	case json.Number:
		return token{vv.String(), tkNumber}
	case string:
		return token{gronQuote(vv), tkString}
	case bool:
		if vv {
			return token{"true", tkTrue}
		}
		return token{"false", tkFalse}
	case float64:
		return token{strconv.FormatFloat(vv, 'g', -1, 64), tkNumber}
	}
	return token{"null", tkNull}
}

// statementList is a sortable collection of statements.
type statementList []statement

// collect walks the value depth first, adding a statement for every node.
func (ss *statementList) collect(path statement, v interface{}) {
	*ss = append(*ss, path.assign(valueToken(v)))
	switch vv := v.(type) {
	case map[string]interface{}:
		for k, sub := range vv {
			ss.collect(path.withKey(k), sub)
		}
	case []interface{}:
		for i, sub := range vv {
			ss.collect(path.withIndex(i), sub)
		}
	}
}

func (ss statementList) Len() int      { return len(ss) }
func (ss statementList) Swap(i, j int) { ss[i], ss[j] = ss[j], ss[i] }

// Less orders statements token by token so that array indexes are compared
// numerically and shorter paths come before their children.
func (ss statementList) Less(i, j int) bool {
	a, b := ss[i], ss[j]
	for n := range a {
		if n >= len(b) {
			return false
		}
		ta, tb := a[n], b[n]
		if ta == tb {
			continue
		}
		if ta.kind == tkEquals {
			return true
		}
		if tb.kind == tkEquals {
			return false
		}
		if ta.kind == tkNumericKey && tb.kind == tkNumericKey {
			ia, _ := strconv.Atoi(ta.text)
			ib, _ := strconv.Atoi(tb.text)
			return ia < ib
		}
		if ta.kind == tkNumber && tb.kind == tkNumber {
			fa, _ := strconv.ParseFloat(ta.text, 64)
			fb, _ := strconv.ParseFloat(tb.text, 64)
			return fa < fb
		}
		return ta.text < tb.text
	}
	return true
}

// streamForm renders a statement as a JSON stream line: [[path...],value]
func (s statement) streamForm(p *palette) string {
	var keys []string
	var val token
	for _, t := range s {
		switch t.kind {
		case tkBare:
			keys = append(keys, p.str(gronQuote(t.text)))
		case tkQuotedKey:
			keys = append(keys, p.str(t.text))
		case tkNumericKey:
			keys = append(keys, p.num(t.text))
		default:
			if t.isValue() {
				val = t
			}
		}
	}
	var b strings.Builder
	b.WriteString(p.brace("["))
	b.WriteString(p.brace("["))
	b.WriteString(strings.Join(keys, ","))
	b.WriteString(p.brace("]"))
	b.WriteString(",")
	b.WriteString(val.painted(p))
	b.WriteString(p.brace("]"))
	return b.String()
}
EOF"}

