package main

import (
	"bytes"
	"encoding/json"
	"sort"
	"unicode/utf8"
)

const hexDigits = "0123456789abcdef"

// appendJSONString writes s as a JSON string literal. When html is true the
// characters <, > and & are escaped too.
func appendJSONString(b *bytes.Buffer, s string, html bool) {
	b.WriteByte('"')
	start := 0
	for i := 0; i < len(s); {
		c := s[i]
		if c < utf8.RuneSelf {
			if c >= 0x20 && c != '"' && c != '\\' && (!html || (c != '<' && c != '>' && c != '&')) {
				i++
				continue
			}
			b.WriteString(s[start:i])
			switch c {
			case '"', '\\':
				b.WriteByte('\\')
				b.WriteByte(c)
			case '\b':
				b.WriteString(`\b`)
			case '\f':
				b.WriteString(`\f`)
			case '\n':
				b.WriteString(`\n`)
			case '\r':
				b.WriteString(`\r`)
			case '\t':
				b.WriteString(`\t`)
			default:
				b.WriteString(`\u00`)
				b.WriteByte(hexDigits[c>>4])
				b.WriteByte(hexDigits[c&0xF])
			}
			i++
			start = i
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if r == utf8.RuneError && size == 1 {
			b.WriteString(s[start:i])
			b.WriteString(`\ufffd`)
			i += size
			start = i
			continue
		}
		if r == '\u2028' || r == '\u2029' {
			b.WriteString(s[start:i])
			b.WriteString(`\u202`)
			b.WriteByte(hexDigits[r&0xF])
			i += size
			start = i
			continue
		}
		i += size
	}
	b.WriteString(s[start:])
	b.WriteByte('"')
}

// jsonStringLiteral returns the JSON encoding of s.
func jsonStringLiteral(s string, html bool) string {
	var b bytes.Buffer
	appendJSONString(&b, s, html)
	return b.String()
}

// marshalScalar encodes a value decoded by encoding/json (without
// UseNumber) the same way json.Marshal would.
func marshalScalar(v interface{}) string {
	switch vv := v.(type) {
	case string:
		return jsonStringLiteral(vv, true)
	case nil:
		return "null"
	case bool:
		if vv {
			return "true"
		}
		return "false"
	case map[string]interface{}:
		return "{}"
	case []interface{}:
		return "[]"
	}
	out, _ := json.Marshal(v)
	return string(out)
}

func sortedKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func writeScalar(b *bytes.Buffer, v interface{}) {
	switch vv := v.(type) {
	case nil:
		b.WriteString("null")
	case bool:
		if vv {
			b.WriteString("true")
		} else {
			b.WriteString("false")
		}
	case json.Number:
		s := vv.String()
		if s == "" {
			s = "0"
		}
		b.WriteString(s)
	case string:
		appendJSONString(b, vv, false)
	case float64:
		out, _ := json.Marshal(vv)
		b.Write(out)
	}
}

func writeIndent(b *bytes.Buffer, depth int) {
	b.WriteByte('\n')
	for i := 0; i < depth; i++ {
		b.WriteString("  ")
	}
}

// writeIndented writes v as indented JSON (two spaces, no HTML escaping).
func writeIndented(b *bytes.Buffer, v interface{}, depth int) {
	switch vv := v.(type) {
	case map[string]interface{}:
		if len(vv) == 0 {
			b.WriteString("{}")
			return
		}
		b.WriteByte('{')
		for i, k := range sortedKeys(vv) {
			if i > 0 {
				b.WriteByte(',')
			}
			writeIndent(b, depth+1)
			appendJSONString(b, k, false)
			b.WriteString(": ")
			writeIndented(b, vv[k], depth+1)
		}
		writeIndent(b, depth)
		b.WriteByte('}')
	case []interface{}:
		if len(vv) == 0 {
			b.WriteString("[]")
			return
		}
		b.WriteByte('[')
		for i, e := range vv {
			if i > 0 {
				b.WriteByte(',')
			}
			writeIndent(b, depth+1)
			writeIndented(b, e, depth+1)
		}
		writeIndent(b, depth)
		b.WriteByte(']')
	default:
		writeScalar(b, v)
	}
}

// stripQuotes removes the surrounding quotes from an encoded string.
func stripQuotes(s string) string {
	return s[1 : len(s)-1]
}

// writeColoured writes v as compact JSON with colour codes.
func writeColoured(b *bytes.Buffer, v interface{}, p *palette) {
	switch vv := v.(type) {
	case map[string]interface{}:
		b.WriteString(p.brace("{"))
		for i, k := range sortedKeys(vv) {
			if i > 0 {
				b.WriteString(p.punct(","))
			}
			b.WriteString(p.bare(`"`))
			b.WriteString(p.bare(stripQuotes(jsonStringLiteral(k, false))))
			b.WriteString(p.bare(`"`))
			b.WriteString(p.punct(":"))
			writeColoured(b, vv[k], p)
		}
		b.WriteString(p.brace("}"))
	case []interface{}:
		b.WriteString(p.brace("["))
		for i, e := range vv {
			if i > 0 {
				b.WriteString(p.punct(","))
			}
			writeColoured(b, e, p)
		}
		b.WriteString(p.brace("]"))
	case string:
		b.WriteString(p.quote(`"`))
		b.WriteString(p.str(stripQuotes(jsonStringLiteral(vv, false))))
		b.WriteString(p.quote(`"`))
	case nil, bool:
		var tmp bytes.Buffer
		writeScalar(&tmp, v)
		b.WriteString(p.lit(tmp.String()))
	default:
		var tmp bytes.Buffer
		writeScalar(&tmp, v)
		b.WriteString(p.num(tmp.String()))
	}
}
EOF"}

