		return nil
	}
	l.emit(tkRBrace)
	return lexStart
}

func lexAssign(l *lineLexer) stateFn {
	l.acceptRun(" ")
	l.skip()
	if !l.accept("=") {
		return nil
	}
	l.emit(tkEquals)
	l.acceptRun(" ")
	l.skip()

	switch {
	case l.accept(`"`):
		l.readToUnescaped(`"`)
		l.accept(`"`)
		l.emit(tkString)
	case l.accept("t"):
		l.acceptRun("rue")
		l.emit(tkTrue)
	case l.accept("f"):
		l.acceptRun("alse")
