	case l.accept("n"):
		l.acceptRun("ul")
		l.emit(tkNull)
	case l.accept("["):
		l.accept("]")
		l.emit(tkEmptyArray)
	case l.accept("{"):
		l.accept("}")
		l.emit(tkEmptyObject)
	default:
		l.readTo(";")
		l.emit(tkNumber)
	}

	l.acceptRun(" ")
	l.skip()
	if l.accept(";") {
		l.emit(tkSemi)
	}
	return nil
}
