{"command":"cd /workspace && cat > ungron.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

var errLayout = errors.New("invalid JSON layout")

// statementFromStream converts a JSON stream line ([[path...],value]) into
// gron tokens.
func statementFromStream(line string) (statement, error) {
	var parts []interface{}
	if err := json.Unmarshal([]byte(line), &parts); err != nil {
		return nil, err
	}
	if len(parts) != 2 {
		return nil, errLayout
	}
	path, ok := parts[0].([]interface{})
	if !ok {
		return nil, errLayout
	}
	s := statement{{"json", tkBare}}
	for _, p := range path {
		switch pv := p.(type) {
		case string:
			s = append(s, token{"[", tkLBrace}, token{marshalScalar(pv), tkQuotedKey}, token{"]", tkRBrace})
		case float64:
			s = append(s, token{"[", tkLBrace}, token{marshalScalar(pv), tkNumericKey}, token{"]", tkRBrace})
		default:
			return nil, errLayout
		}
	}
	var val token
	switch vv := parts[1].(type) {
	case map[string]interface{}:
		if len(vv) > 0 {
			return nil, errLayout
		}
		val = token{"{}", tkEmptyObject}
	case []interface{}:
		if len(vv) > 0 {
			return nil, errLayout
		}
		val = token{"[]", tkEmptyArray}
	case string:
		val = token{marshalScalar(vv), tkString}
	case float64:
		val = token{marshalScalar(vv), tkNumber}
	case bool:
		if vv {
			val = token{"true", tkTrue}
		} else {
			val = token{"false", tkFalse}
		}
	default:
		val = token{"null", tkNull}
	}
	s = append(s, token{"=", tkEquals}, val, token{";", tkSemi})
	return s, nil
}

// decodeValue parses a value token the way a streaming JSON decoder would:
// the first complete value is used and anything after it is ignored.
func decodeValue(text string) (interface{}, error) {
	dec := json.NewDecoder(strings.NewReader(text))
	dec.UseNumber()
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		return nil, err
	}
	return v, nil
}

// buildValue turns the tokens of a statement into a nested value.
func buildValue(ts statement) (interface{}, error) {
	if len(ts) == 0 {
		return nil, errors.New("statement has no value")
	}
	t := ts[0]
	switch t.kind {
	case tkBare:
		inner, err := buildValue(ts[1:])
		if err != nil {
			return nil, err
		}
		return map[string]interface{}{t.text: inner}, nil

	case tkQuotedKey:
		inner, err := buildValue(ts[1:])
		if err != nil {
			return nil, err
		}
		var key string
		if err := json.Unmarshal([]byte(t.text), &key); err != nil {
			return nil, fmt.Errorf("invalid quoted key `%s`", t.text)
		}
		return map[string]interface{}{key: inner}, nil

	case tkNumericKey:
		idx, err := strconv.Atoi(t.text)
		if err != nil {
			return nil, fmt.Errorf("invalid integer key `%s`", t.text)
		}
		inner, err := buildValue(ts[1:])
		if err != nil {
			return nil, err
		}
		arr := make([]interface{}, idx+1)
		arr[idx] = inner
		return arr, nil

	case tkEquals:
		if len(ts) < 2 {
			return nil, errors.New("statement has no value")
		}
		v, err := decodeValue(ts[1].text)
		if err != nil {
			return nil, fmt.Errorf("invalid value `%s`", ts[1].text)
		}
		return v, nil
	}
	return buildValue(ts[1:])
}

// mergeValues merges b into a.
func mergeValues(a, b interface{}) (interface{}, error) {
	switch av := a.(type) {
	case map[string]interface{}:
		bm, ok := b.(map[string]interface{})
		if !ok {
			return nil, errors.New("cannot merge object with non-object")
		}
		for k, bv := range bm {
			if existing, found := av[k]; found {
				m, err := mergeValues(existing, bv)
				if err != nil {
					return nil, err
				}
				av[k] = m
			} else {
				av[k] = bv
			}
		}
		return av, nil

	case []interface{}:
		ba, ok := b.([]interface{})
		if !ok {
			return nil, errors.New("cannot merge array with non-array")
		}
		for i, bv := range ba {
			if i >= len(av) {
				av = append(av, bv)
				continue
			}
			if bv == nil {
				continue
			}
			m, err := mergeValues(av[i], bv)
			if err != nil {
				return nil, err
			}
			av[i] = m
		}
		return av, nil
	}
	return b, nil
}

func hasErrorToken(s statement) bool {
	for _, t := range s {
		if t.kind == tkError {
			return true
		}
	}
	return false
}

// runUngron turns gron statements back into JSON.
func runUngron(r io.Reader, w io.Writer, o options) (int, error) {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64*1024), 1024*1024)

	var all []statement
	for sc.Scan() {
		line := sc.Text()
		if o.jsonStream {
			s, err := statementFromStream(line)
			if err != nil {
				return exitParseStatements, err
			}
			all = append(all, s)
			continue
		}
		s := tokenize(line)
		if len(s) == 0 || (len(s) == 1 && s[0].kind != tkError) {
			continue
		}
		all = append(all, s)
	}
	if err := sc.Err(); err != nil {
		return exitReadInput, errors.New("failed to read input statements")
	}

	if len(all) == 0 {
		return exitParseStatements, errors.New("no statements were parsed")
	}

	values := make([]interface{}, 0, len(all))
	for _, s := range all {
		if hasErrorToken(s) {
			return exitParseStatements, fmt.Errorf("ungron failed for `%s`: invalid statement", s.plain())
		}
		if s[len(s)-1].kind != tkSemi {
			return exitParseStatements, fmt.Errorf("ungron failed for `%s`: statement has no value", s.plain())
		}
		v, err := buildValue(s)
		if err != nil {
			return exitParseStatements, fmt.Errorf("ungron failed for `%s`: %s", s.plain(), err)
		}
		values = append(values, v)
	}

	var merged interface{}
	for i, v := range values {
		if i == 0 {
			merged = v
			continue
		}
		m, err := mergeValues(merged, v)
		if err != nil {
			return exitParseStatements, fmt.Errorf("failed to merge statements: %s", err)
		}
		merged = m
	}

	if m, ok := merged.(map[string]interface{}); ok && len(m) == 1 {
		if inner, found := m["json"]; found {
			merged = inner
		}
	}

	var b bytes.Buffer
	if o.monochrome {
		writeIndented(&b, merged, 0)
	} else {
		writeColoured(&b, merged, o.pal)
	}
	b.WriteByte('\n')
	if _, err := w.Write(b.Bytes()); err != nil {
		return exitJSONEncode, err
	}
	return exitOK, nil
}
EOF"}

