package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strconv"
)

// options collects the behaviour switches given on the command line.
type options struct {
	monochrome bool
	jsonStream bool
	sorted     bool
	pal        *palette
}

func rootPath() statement {
	return statement{{"json", tkBare}}
}

// render formats a single statement for output.
func render(s statement, o options) string {
	if o.jsonStream {
		return s.streamForm(o.pal)
	}
	if o.monochrome {
		return s.plain()
	}
	return s.painted(o.pal)
}

func writeStatements(w *bufio.Writer, ss statementList, o options) {
	if o.sorted {
		sort.Sort(ss)
	}
	for _, s := range ss {
		w.WriteString(render(s, o))
		w.WriteByte('\n')
	}
}

// runGron converts a single JSON document into gron statements.
func runGron(r io.Reader, w io.Writer, o options) (int, error) {
	dec := json.NewDecoder(r)
	dec.UseNumber()
	var top interface{}
	if err := dec.Decode(&top); err != nil {
		return exitFormStatements, fmt.Errorf("failed to form statements: %s", err)
	}
	var ss statementList
	ss.collect(rootPath(), top)

	bw := bufio.NewWriter(w)
	writeStatements(bw, ss, o)
	bw.Flush()
	return exitOK, nil
}

// runStream treats every input line as a separate JSON document.
func runStream(r io.Reader, w io.Writer, o options) (int, error) {
	bw := bufio.NewWriter(w)
	defer bw.Flush()

	bw.WriteString(render(rootPath().assign(token{"[]", tkEmptyArray}), o))
	bw.WriteByte('\n')
	bw.Flush()

	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64*1024), 1024*1024)
	i := 0
	for sc.Scan() {
		dec := json.NewDecoder(bytes.NewReader(sc.Bytes()))
		dec.UseNumber()
		var v interface{}
		if err := dec.Decode(&v); err != nil {
			return exitFormStatements, fmt.Errorf("failed to form statements: %s", err)
		}
		var ss statementList
		ss.collect(rootPath().withIndex(i), v)
		writeStatements(bw, ss, o)
		bw.Flush()
		i++
	}
	if err := sc.Err(); err != nil {
		return exitFormStatements, fmt.Errorf("error reading multiline input: %s: %s", err.Error(), "%!s(MISSING)")
	}
	return exitOK, nil
}

// runValues prints just the values of the statements read from stdin.
func runValues(r io.Reader, w io.Writer) (int, error) {
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		line := sc.Text()
		s := tokenize(line)
		if len(s) == 0 {
			return exitParseStatements, fmt.Errorf("failed to parse '%s' as gron statement", line)
		}
		if s[0].kind == tkBare && s[0].text == "json" {
			s = s[1:]
		}
		// an empty remainder is an error the same way indexing it would be
		if s[0].kind == tkDot || s[0].kind == tkLBrace {
			s = s[1:]
		}
		for _, t := range s {
			switch t.kind {
			case tkString:
				var str string
				if err := json.Unmarshal([]byte(t.text), &str); err != nil {
					continue
				}
				fmt.Fprintln(w, str)
			case tkNumber, tkTrue, tkFalse, tkNull:
				fmt.Fprintln(w, t.text)
			}
		}
	}
	return exitOK, nil
}

var _ = strconv.Itoa
EOF"}

