package main

import (
	"bufio"
	"crypto/tls"
	"io"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"strings"
	"time"
)

var urlPattern = regexp.MustCompile(`(?i)^https?://`)

func looksLikeURL(s string) bool {
	return urlPattern.MatchString(s)
}

// proxySettings holds the proxy configuration from flags and environment.
type proxySettings struct {
	proxy      string
	proxySet   bool
	noProxy    string
	noProxySet bool
}

// hostExcluded reports whether host matches one of the comma separated
// entries in list. Entries starting with a dot match as suffixes.
func hostExcluded(host, list string) bool {
	for _, entry := range strings.Split(list, ",") {
		if entry == host {
			return true
		}
		if strings.HasPrefix(entry, ".") && strings.HasSuffix(host, entry) {
			return true
		}
	}
	return false
}

func chooseProxy(target string, ps proxySettings) *url.URL {
	u, err := url.Parse(target)
	if err != nil {
		return nil
	}
	noProxy := ps.noProxy
	if !ps.noProxySet {
		noProxy = os.Getenv("no_proxy")
	}
	if hostExcluded(u.Host, noProxy) {
		return nil
	}
	proxy := ps.proxy
	if !ps.proxySet {
		if u.Scheme == "https" {
			proxy = os.Getenv("https_proxy")
		} else {
			proxy = os.Getenv("http_proxy")
		}
	}
	if proxy == "" {
		return nil
	}
	pu, err := url.Parse(proxy)
	if err != nil {
		return nil
	}
	return pu
}

// fetch performs a GET request and returns the response body.
func fetch(target string, insecure bool, ps proxySettings) (io.Reader, error) {
	tr := &http.Transport{
		TLSClientConfig: &tls.Config{InsecureSkipVerify: insecure},
	}
	if pu := chooseProxy(target, ps); pu != nil {
		tr.Proxy = http.ProxyURL(pu)
	}
	client := http.Client{
		Transport: tr,
		Timeout:   20 * time.Second,
	}

	req, err := http.NewRequest("GET", target, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "gron/"+gronVersion)
	req.Header.Set("Accept", "application/json")

	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	return bufio.NewReader(resp.Body), nil
}
EOF
