package main

import (
	"flag"
	"fmt"
	"io"
	"os"
)

const gronVersion = "dev"

const (
	exitOK = iota
	exitOpenFile
	exitReadInput
	exitFormStatements
	exitFetchURL
	exitParseStatements
	exitJSONEncode
)

func die(code int, err error) {
	fmt.Fprintln(os.Stderr, err)
	os.Exit(code)
}

func main() {
	var (
		ungronFlag     bool
		colorizeFlag   bool
		monochromeFlag bool
		streamFlag     bool
		noSortFlag     bool
		versionFlag    bool
		insecureFlag   bool
		jsonFlag       bool
		valuesFlag     bool
		proxyFlag      string
		noProxyFlag    string
	)

	flag.Usage = func() {
		fmt.Fprint(os.Stderr, usageText)
	}

	flag.BoolVar(&ungronFlag, "ungron", false, "")
	flag.BoolVar(&ungronFlag, "u", false, "")
	flag.BoolVar(&colorizeFlag, "colorize", false, "")
	flag.BoolVar(&colorizeFlag, "c", false, "")
	flag.BoolVar(&monochromeFlag, "monochrome", false, "")
	flag.BoolVar(&monochromeFlag, "m", false, "")
	flag.BoolVar(&streamFlag, "s", false, "")
	flag.BoolVar(&streamFlag, "stream", false, "")
	flag.BoolVar(&noSortFlag, "no-sort", false, "")
	flag.BoolVar(&versionFlag, "version", false, "")
	flag.BoolVar(&insecureFlag, "k", false, "")
	flag.BoolVar(&insecureFlag, "insecure", false, "")
	flag.BoolVar(&jsonFlag, "j", false, "")
	flag.BoolVar(&jsonFlag, "json", false, "")
	flag.BoolVar(&valuesFlag, "values", false, "")
	flag.BoolVar(&valuesFlag, "value", false, "")
	flag.BoolVar(&valuesFlag, "v", false, "")
	flag.StringVar(&proxyFlag, "x", "", "")
	flag.StringVar(&proxyFlag, "proxy", "", "")
	flag.StringVar(&noProxyFlag, "noproxy", "", "")

	flag.Parse()

	if versionFlag {
		fmt.Printf("gron version %s\n", gronVersion)
		os.Exit(exitOK)
	}

	ps := proxySettings{proxy: proxyFlag, noProxy: noProxyFlag}
	flag.Visit(func(f *flag.Flag) {
		switch f.Name {
		case "x", "proxy":
			ps.proxySet = true
		case "noproxy":
			ps.noProxySet = true
		}
	})

	var input io.Reader
	name := flag.Arg(0)
	switch {
	case name == "" || name == "-":
		input = os.Stdin
	case looksLikeURL(name):
		r, err := fetch(name, insecureFlag, ps)
		if err != nil {
			die(exitFetchURL, err)
		}
		input = r
	default:
		f, err := os.Open(name)
		if err != nil {
			die(exitOpenFile, err)
		}
		defer f.Close()
		input = f
	}

	mono := defaultMonochrome()
	if monochromeFlag {
		mono = true
	}
	if colorizeFlag {
		mono = false
	}

	o := options{
		monochrome: mono,
		jsonStream: jsonFlag,
		sorted:     !noSortFlag,
		pal:        &palette{codes: !mono && !colourEnvDisabled()},
	}

	var code int
	var err error
	switch {
	case ungronFlag:
		code, err = runUngron(input, os.Stdout, o)
	case valuesFlag:
		code, err = runValues(os.Stdin, os.Stdout)
	case streamFlag:
		code, err = runStream(input, os.Stdout, o)
	default:
		code, err = runGron(input, os.Stdout, o)
	}
	if err != nil {
		die(code, err)
	}
	os.Exit(code)
}
