	"sort"
	"strconv"
	"strings"
)

// statement is a gron assignment, e.g. json.a[0] = "x";
type statement []token

// plain renders the statement without colour.
func (s statement) plain() string {
	var b strings.Builder
	for _, t := range s {
		b.WriteString(t.plain())
	}
	return b.String()
}

// valueToken converts a decoded JSON value into its gron value token.
func valueToken(v interface{}) token {
	switch vv := v.(type) {
	case map[string]interface{}:
		return token{"{}", tkEmptyObject}
	case []interface{}:
		return token{"[]", tkEmptyArray}
	case json.Number:
		return token{vv.String(), tkNumber}
	case string:
		return token{gronQuote(vv), tkString}
	case bool:
		if vv {
			return token{"true", tkTrue}
		}
		return token{"false", tkFalse}
	case float64:
		return token{strconv.FormatFloat(vv, 'g', -1, 64), tkNumber}
	}
	return token{"null", tkNull}
}

// childKey is an object key together with the form it takes in a path.
type childKey struct {
	raw    string
	text   string
	quoted bool
}

func makeChildKey(k string) childKey {
	if isBareKey(k) {
		return childKey{raw: k, text: k}
	}
	return childKey{raw: k, text: gronQuote(k), quoted: true}
}

// sortChildKeys orders keys the way full statements compare: bare keys
// (introduced by '.') come before quoted keys (introduced by '['), and each
// group is ordered by its textual form.
func sortChildKeys(keys []childKey) {
	sort.Slice(keys, func(i, j int) bool {
		a, b := keys[i], keys[j]
		if a.quoted != b.quoted {
			return !a.quoted
		}
		return a.text < b.text
	})
}

// emitter walks a decoded JSON value and writes one statement per node.
type emitter struct {
	w    *bufio.Writer
	o    options
	path []byte // rendered form of the current path
	// depth of the current path in keys, used for stream form separators
	keys int
}

func newEmitter(w *bufio.Writer, o options) *emitter {
	e := &emitter{w: w, o: o}
	if !o.jsonStream {
		e.path = append(e.path, e.paint(token{"json", tkBare})...)
	}
	return e
}

func (e *emitter) paint(t token) string {
	if e.o.monochrome {
		return t.plain()
	}
	return t.painted(e.o.pal)
}

// pushKey appends an object key to the path and returns the previous length.
func (e *emitter) pushKey(k childKey) int {
	n := len(e.path)
	if e.o.jsonStream {
		if e.keys > 0 {
			e.path = append(e.path, ',')
		}
		if k.quoted {
			e.path = append(e.path, e.o.pal.str(k.text)...)
		} else {
			e.path = append(e.path, e.o.pal.str(gronQuote(k.text))...)
		}
	} else if k.quoted {
		e.path = append(e.path, e.paint(token{"[", tkLBrace})...)
		e.path = append(e.path, e.paint(token{k.text, tkQuotedKey})...)
		e.path = append(e.path, e.paint(token{"]", tkRBrace})...)
	} else {
		e.path = append(e.path, '.')
		e.path = append(e.path, e.paint(token{k.text, tkBare})...)
	}
	e.keys++
	return n
}

// pushIndex appends an array index to the path and returns the previous length.
func (e *emitter) pushIndex(i int) int {
	n := len(e.path)
	idx := strconv.Itoa(i)
	if e.o.jsonStream {
		if e.keys > 0 {
			e.path = append(e.path, ',')
		}
		e.path = append(e.path, e.o.pal.num(idx)...)
	} else {
		e.path = append(e.path, e.paint(token{"[", tkLBrace})...)
		e.path = append(e.path, e.paint(token{idx, tkNumericKey})...)
		e.path = append(e.path, e.paint(token{"]", tkRBrace})...)
	}
	e.keys++
	return n
}

func (e *emitter) pop(n int) {
	e.path = e.path[:n]
	e.keys--
}

// statement writes the assignment of v to the current path.
func (e *emitter) statement(v token) {
	if e.o.jsonStream {
		p := e.o.pal
		e.w.WriteString(p.brace("["))
		e.w.WriteString(p.brace("["))
		e.w.Write(e.path)
		e.w.WriteString(p.brace("]"))
		e.w.WriteByte(',')
		e.w.WriteString(e.paint(v))
		e.w.WriteString(p.brace("]"))
		e.w.WriteByte('\n')
		return
	}
	e.w.Write(e.path)
	e.w.WriteString(" = ")
	e.w.WriteString(e.paint(v))
	e.w.WriteString(";\n")
}

// walk emits statements for v and all of its descendants.
func (e *emitter) walk(v interface{}) {
	e.statement(valueToken(v))
	switch vv := v.(type) {
	case map[string]interface{}:
		if !e.o.sorted {
			for k, sub := range vv {
				n := e.pushKey(makeChildKey(k))
				e.walk(sub)
				e.pop(n)
			}
			return
		}
		keys := make([]childKey, 0, len(vv))
		for k := range vv {
			keys = append(keys, makeChildKey(k))
		}
		sortChildKeys(keys)
		for _, k := range keys {
			n := e.pushKey(k)
			e.walk(vv[k.raw])
			e.pop(n)
		}
	case []interface{}:
		for i, sub := range vv {
			n := e.pushIndex(i)
			e.walk(sub)
			e.pop(n)
		}
	}
}
